    fn can_parse_expr(&self) -> bool { self.can_parse_ident_expr() || self.can_parse_string_expr() || self.can_parse_number_expr() || self.can_parse_ctor_expr() || self.can_parse_thunk_expr() || self.can_parse_roll_expr() || self.can_parse_bundle_expr() || self.can_parse_produce_expr() || self.can_parse_force_expr() || self.can_parse_lambda_expr() || self.can_parse_let_expr() || self.can_parse_match_expr() || self.can_parse_unroll_expr() || self.can_parse_perform_expr() || self.can_parse_handle_expr() || self.can_parse_ann_expr() || self.can_parse_error_expr() }
    fn parse_expr(&mut self) -> SyntaxNode {
        // Parse a primary expression first
        let mut lhs = if self.can_parse_ident_expr() { self.parse_ident_expr() }
        else if self.can_parse_string_expr() { self.parse_string_expr() }
        else if self.can_parse_number_expr() { self.parse_number_expr() }
        else if self.can_parse_ctor_expr() { self.parse_ctor_expr() }
        else if self.can_parse_thunk_expr() { self.parse_thunk_expr() }
        else if self.can_parse_roll_expr() { self.parse_roll_expr() }
        else if self.can_parse_bundle_expr() { self.parse_bundle_expr() }
        else if self.can_parse_produce_expr() { self.parse_produce_expr() }
        else if self.can_parse_force_expr() { self.parse_force_expr() }
        else if self.can_parse_lambda_expr() { self.parse_lambda_expr() }
        else if self.can_parse_let_expr() { self.parse_let_expr() }
        else if self.can_parse_match_expr() { self.parse_match_expr() }
        else if self.can_parse_unroll_expr() { self.parse_unroll_expr() }
        else if self.can_parse_perform_expr() { self.parse_perform_expr() }
        else if self.can_parse_handle_expr() { self.parse_handle_expr() }
        else if self.can_parse_ann_expr() { self.parse_ann_expr() }
        else if self.can_parse_error_expr() { self.parse_error_expr() }
        else {
            self.error_here("expected Expr");
            return node_from_children(SyntaxKind::ERROR, Vec::new());
        };

        // Parse postfix Apply and Member suffixes (handles left-recursion)
        loop {
            if self.at_non_trivia_symbol("(") {
                // ApplyExpr: callee '(' arg ')'
                let mut children = Vec::new();
                children.push(SyntaxElement::Node(Box::new(lhs)));
                self.expect_symbol("(", &mut children);
                children.push(SyntaxElement::Node(Box::new(self.parse_expr())));
                self.expect_symbol(")", &mut children);
                lhs = node_from_children(SyntaxKind::APPLY_EXPR, children);
            } else if self.peek_kind_at(0) == Some(LexKind::Symbol(lumo_lexer::Symbol::Dot))
                && matches!(self.peek_kind_at(1), Some(LexKind::Ident)) {
                // MemberExpr: object '.' field
                let mut children = Vec::new();
                children.push(SyntaxElement::Node(Box::new(lhs)));
                self.expect_symbol(".", &mut children);
                self.skip_trivia_into(&mut children);
                if matches!(self.current().map(|t| &t.kind), Some(LexKind::Ident)) {
                    children.push(SyntaxElement::Token(self.bump().unwrap()));
                } else { self.error_here("expected Ident after '.'"); }
                lhs = node_from_children(SyntaxKind::MEMBER_EXPR, children);
            } else {
                break;
            }
        }
        lhs
    }

    fn can_parse_ident_expr(&self) -> bool { self.at_non_trivia_ident() }
    fn parse_ident_expr(&mut self) -> SyntaxNode {
        let mut children = Vec::new();
        self.skip_trivia_into(&mut children);
        if matches!(self.current().map(|t| &t.kind), Some(LexKind::Ident)) {
            children.push(SyntaxElement::Token(self.bump().unwrap()));
        } else { self.error_here("expected Ident"); }
        node_from_children(SyntaxKind::IDENT_EXPR, children)
    }

