    fn can_parse_ctor_expr(&self) -> bool { self.at_non_trivia_keyword(Keyword::Ctor) }
    fn parse_ctor_expr(&mut self) -> SyntaxNode {
        let mut children = Vec::new();
        self.expect_keyword(Keyword::Ctor, &mut children);
        self.skip_trivia_into(&mut children);
        if matches!(self.current().map(|t| &t.kind), Some(LexKind::Ident)) {
            children.push(SyntaxElement::Token(self.bump().unwrap()));
        } else { self.error_here("expected Ident"); }
        // Handle dotted ctor names like Bool.false — consume `.Ident` as part of name
        while self.peek_kind_at(0) == Some(LexKind::Symbol(lumo_lexer::Symbol::Dot))
            && matches!(self.peek_kind_at(1), Some(LexKind::Ident))
        {
            self.skip_trivia_into(&mut children);
            if self.at_symbol_text(".") {
                children.push(SyntaxElement::Token(self.bump().unwrap()));
            }
            self.skip_trivia_into(&mut children);
            if matches!(self.current().map(|t| &t.kind), Some(LexKind::Ident)) {
                // Merge the dot and following ident into the previous IDENT token text
                // We do this by creating a synthetic token with combined text
                let dot_text = ".";
                let variant_tok = self.bump().unwrap();
                // Remove the dot token we just pushed
                let dot_token = children.pop().unwrap();
                // Also remove whitespace before dot if any
                while let Some(SyntaxElement::Token(t)) = children.last() {
                    if t.kind == SyntaxKind::WHITESPACE || t.kind == SyntaxKind::NEWLINE {
                        children.pop();
                    } else {
                        break;
                    }
                }
                // Get the previous ident token and extend it
                if let Some(SyntaxElement::Token(prev)) = children.last_mut() {
                    let combined = format!("{}{}{}", prev.text, dot_text, variant_tok.text);
                    let new_span = lumo_span::Span::new(prev.span.start, variant_tok.span.end);
                    *prev = LosslessToken {
                        kind: SyntaxKind::IDENT,
                        span: new_span,
                        text: combined,
                    };
                } else {
                    // Shouldn't happen: push dot and variant separately as fallback
                    children.push(dot_token);
                    children.push(SyntaxElement::Token(variant_tok));
                }
            } else {
                self.error_here("expected Ident after '.'");
            }
        }
        if self.can_parse_ctor_args() {
            children.push(SyntaxElement::Node(Box::new(self.parse_ctor_args())));
        }
        node_from_children(SyntaxKind::CTOR_EXPR, children)
    }

    fn can_parse_ctor_args(&self) -> bool { self.at_non_trivia_symbol("(") }
    fn parse_ctor_args(&mut self) -> SyntaxNode {
        let mut children = Vec::new();
        self.expect_symbol("(", &mut children);
        if self.can_parse_ctor_arg_items() {
            children.push(SyntaxElement::Node(Box::new(self.parse_ctor_arg_items())));
        }
        self.expect_symbol(")", &mut children);
        node_from_children(SyntaxKind::CTOR_ARGS, children)
    }

